ALTER TABLE users ADD COLUMN failed_attempts INT NOT NULL DEFAULT 0;
ALTER TABLE users ADD COLUMN locked_until TIMESTAMPTZ;
ALTER TABLE users ADD COLUMN token_version INT NOT NULL DEFAULT 0;
ALTER TABLE rooms ADD COLUMN amenities TEXT NOT NULL DEFAULT '';
ALTER TABLE rooms ADD COLUMN internal_note TEXT NOT NULL DEFAULT '';
ALTER TABLE contracts ADD COLUMN terms TEXT NOT NULL DEFAULT '';
ALTER TABLE contracts ADD COLUMN violation_note TEXT;
ALTER TABLE contracts ADD COLUMN actual_checkout_date DATE;
CREATE TABLE room_images (id BIGSERIAL PRIMARY KEY, room_id BIGINT NOT NULL REFERENCES rooms(id), url TEXT NOT NULL);
CREATE TABLE room_price_history (id BIGSERIAL PRIMARY KEY, room_id BIGINT NOT NULL REFERENCES rooms(id), old_price NUMERIC(12,2), new_price NUMERIC(12,2) NOT NULL, changed_by BIGINT REFERENCES users(id), changed_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE auth_sessions (id BIGSERIAL PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users(id), token_hash VARCHAR(64) NOT NULL UNIQUE, expires_at TIMESTAMPTZ NOT NULL);
CREATE TABLE password_reset_codes (id BIGSERIAL PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users(id), code_hash VARCHAR(64) NOT NULL, expires_at TIMESTAMPTZ NOT NULL, used BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE audit_logs (id BIGSERIAL PRIMARY KEY, user_id BIGINT REFERENCES users(id), action VARCHAR(100) NOT NULL, resource_type VARCHAR(100) NOT NULL, resource_id BIGINT, before_data TEXT, after_data TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE meter_reading_history (id BIGSERIAL PRIMARY KEY, meter_reading_id BIGINT NOT NULL REFERENCES meter_readings(id), old_value NUMERIC(10,2) NOT NULL, new_value NUMERIC(10,2) NOT NULL, changed_by BIGINT NOT NULL REFERENCES users(id), reason TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE notifications (id BIGSERIAL PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users(id), type VARCHAR(40) NOT NULL, message TEXT NOT NULL, reference_key VARCHAR(150) NOT NULL, is_read BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(user_id, reference_key));
CREATE TABLE maintenance_requests (id BIGSERIAL PRIMARY KEY, contract_id BIGINT REFERENCES contracts(id), property_id BIGINT NOT NULL REFERENCES properties(id), room_id BIGINT REFERENCES rooms(id), submitted_by BIGINT NOT NULL REFERENCES users(id), assigned_to BIGINT REFERENCES users(id), title VARCHAR(150) NOT NULL, description TEXT NOT NULL, category VARCHAR(50) NOT NULL DEFAULT 'OTHER', priority VARCHAR(20) NOT NULL CHECK(priority IN ('URGENT','NORMAL','LOW')), status VARCHAR(20) NOT NULL DEFAULT 'NEW' CHECK(status IN ('NEW','ACCEPTED','IN_PROGRESS','COMPLETED')), image_urls TEXT NOT NULL DEFAULT '', expected_date DATE NOT NULL, actual_cost NUMERIC(12,2) NOT NULL DEFAULT 0 CHECK(actual_cost>=0), progress_note TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE maintenance_schedules (id BIGSERIAL PRIMARY KEY, property_id BIGINT NOT NULL REFERENCES properties(id), title VARCHAR(150) NOT NULL, next_date DATE NOT NULL, interval_days INT NOT NULL CHECK(interval_days>0), notes TEXT);
CREATE INDEX idx_notifications_user ON notifications(user_id, is_read);
CREATE INDEX idx_maintenance_property ON maintenance_requests(property_id, status);
CREATE INDEX idx_audit_created ON audit_logs(created_at);
